	BarPeriod = 1440;
	StartDate = 20080101;
	EndDate   = 20240101;
	LookBack  = 0;
	asset("EUR/USD");

	if(is(INITRUN)) {
		mst_n = 0; mst_done = 0; mst_hdr = 0; mst_rows = 0; mst_sgn = 1;	// declared initialisers
		file_delete(MST_RAW);
		file_delete(MST_MARK);
		return;
	}
	if(is(EXITRUN)) {
		printf("\nMST EXIT: rows written = %d, done = %d  (expected 3000 and 1)", mst_rows, mst_done);
		// marker file: if it exists after the run, EXITRUN ran even if the printf was lost (gotchas 9d.4)
		file_append(MST_MARK, strf("EXITRUN ran: rows=%d done=%d\n", mst_rows, mst_done), 0);
		return;
	}

	int n;
	var X[18];
	var Y[368];
	var mst_o_roof;
	var mst_o_stoc;
	n = mst_n;

	// --- constants built at RUN TIME from integers (gotchas 9d.1, 9d.2) ---
	var lvl = 11;	lvl = lvl / 10;
	var amp = 1;	amp = amp / 100;
	var slp = 1;	slp = slp / 10000;
	var pi_x = 4;	pi_x = pi_x * atan(1);
	var lvl_sc = 11;	lvl_sc = lvl_sc / 10;
	var amp_sc = 1;	amp_sc = amp_sc / 10;
	var lvl_of = 22;	lvl_of = lvl_of / 10;
	var amp_of = 1;	amp_of = amp_of / 100;

	// --- inputs from the bar counter (radians); no decimal literal, no PI macro ---
	X[0] = lvl;
	X[1] = lvl + amp * sin(2 * pi_x * n / 5);
	X[2] = lvl + amp * sin(2 * pi_x * n / 10);
	X[3] = lvl + amp * sin(2 * pi_x * n / 20);
	X[4] = lvl + amp * sin(2 * pi_x * n / 40);
	X[5] = lvl + amp * sin(2 * pi_x * n / 100);
	X[6] = lvl + amp * mst_sgn;
	X[7] = lvl + slp * n;
	X[8] = lvl_sc + amp_sc * sin(2 * pi_x * n / 5);
	X[9] = lvl_sc + amp_sc * sin(2 * pi_x * n / 10);
	X[10] = lvl_sc + amp_sc * sin(2 * pi_x * n / 20);
	X[11] = lvl_sc + amp_sc * sin(2 * pi_x * n / 40);
	X[12] = lvl_sc + amp_sc * sin(2 * pi_x * n / 100);
	X[13] = lvl_of + amp_of * sin(2 * pi_x * n / 5);
	X[14] = lvl_of + amp_of * sin(2 * pi_x * n / 10);
	X[15] = lvl_of + amp_of * sin(2 * pi_x * n / 20);
	X[16] = lvl_of + amp_of * sin(2 * pi_x * n / 40);
	X[17] = lvl_of + amp_of * sin(2 * pi_x * n / 100);

	// --- input series: 18 unconditional calls, fixed order ---
	vars S0 = series(X[0], 3);
	vars S1 = series(X[1], 3);
	vars S2 = series(X[2], 3);
	vars S3 = series(X[3], 3);
	vars S4 = series(X[4], 3);
	vars S5 = series(X[5], 3);
	vars S6 = series(X[6], 3);
	vars S7 = series(X[7], 3);
	vars S8 = series(X[8], 3);
	vars S9 = series(X[9], 3);
	vars S10 = series(X[10], 3);
	vars S11 = series(X[11], 3);
	vars S12 = series(X[12], 3);
	vars S13 = series(X[13], 3);
	vars S14 = series(X[14], 3);
	vars S15 = series(X[15], 3);
	vars S16 = series(X[16], 3);
	vars S17 = series(X[17], 3);

	// --- 128 filter calls, variant-major, unconditional, fixed order ---
	Y[2] = MESAStochasticCore(S0, 14, 48, 10, &mst_o_roof, &mst_o_stoc);	// L14 flat
	Y[0] = mst_o_roof;
	Y[1] = mst_o_stoc;
